function transitionGridMask(progress,type){const cols=10,rows=6,rects=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const threshold=type==='randomBlocks'?((x*17+y*31+x*y*13)%61)/60:((x+y)%2)*.42+((x+y)/(cols+rows-2))*.58;if(progress>=threshold)rects.push(`<rect x="${x}" y="${y}" width="1.02" height="1.02" fill="white"/>`)}const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${cols} ${rows}" preserveAspectRatio="none">${rects.join('')}</svg>`;return`url("data:image/svg+xml,${encodeURIComponent(svg)}")`}
function transitionBandSlideMask(progress){const rows=6,width=Math.max(0,Math.min(1,progress))*100,rects=[];for(let y=0;y<rows;y++)rects.push(`<rect x="${y%2?100-width:0}" y="${y*100/rows}" width="${width}" height="${100/rows+.2}" fill="white"/>`);const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" preserveAspectRatio="none">${rects.join('')}</svg>`;return`url("data:image/svg+xml,${encodeURIComponent(svg)}")`}
