if(new URLSearchParams(location.search).has('phasertest')){const report=document.createElement('pre');report.id='phaserTestResult';report.hidden=true;document.body.append(report);(async()=>{try{const rate=48000,length=8192,ctx=new OfflineAudioContext(1,length,rate),source=ctx.createBufferSource(),buffer=ctx.createBuffer(1,length,rate);buffer.getChannelData(0)[0]=1;source.buffer=buffer;const dry=ctx.createGain(),wet=ctx.createGain();dry.gain.value=.75;wet.gain.value=.55;source.connect(dry).connect(ctx.destination);let tail=source;[400,700,1000,1300].forEach(frequency=>{const node=ctx.createBiquadFilter();node.type='allpass';node.frequency.value=frequency;node.Q.value=.7;tail=tail.connect(node)});tail.connect(wet).connect(ctx.destination);source.start();const rendered=await ctx.startRendering(),out=rendered.getChannelData(0),frequencies=[200,500,1000,2000,5000],response=frequencies.map(frequency=>{let re=0,im=0;for(let n=0;n<out.length;n++){const angle=2*Math.PI*frequency*n/rate;re+=out[n]*Math.cos(angle);im-=out[n]*Math.sin(angle)}return{frequency,magnitude:Math.sqrt(re*re+im*im)}}),spread=Math.max(...response.map(x=>x.magnitude))-Math.min(...response.map(x=>x.magnitude));report.textContent=JSON.stringify({passed:spread>.05,spread,response});report.dataset.done='true'}catch(error){report.textContent=JSON.stringify({passed:false,error:String(error)});report.dataset.done='true'}})()}
if(new URLSearchParams(location.search).has('eqbanktest')){const report=document.createElement('pre');report.id='eqBankTestResult';report.hidden=true;document.body.append(report);(async()=>{try{const render=async Q=>{const rate=48000,length=8192,ctx=new OfflineAudioContext(1,length,rate),source=ctx.createBufferSource(),buffer=ctx.createBuffer(1,length,rate);buffer.getChannelData(0)[0]=1;source.buffer=buffer;const eq=ctx.createBiquadFilter();eq.type='peaking';eq.frequency.value=1000;eq.Q.value=Q;eq.gain.value=6;source.connect(eq).connect(ctx.destination);source.start();const out=(await ctx.startRendering()).getChannelData(0),magnitude=frequency=>{let re=0,im=0;for(let n=0;n<out.length;n++){const angle=2*Math.PI*frequency*n/rate;re+=out[n]*Math.cos(angle);im-=out[n]*Math.sin(angle)}return Math.sqrt(re*re+im*im)};return{q:Q,at500:magnitude(500),at1000:magnitude(1000),at2000:magnitude(2000)}};const eq20=await render(2.87),eq30=await render(4.32);report.textContent=JSON.stringify({passed:eq20.at1000>1.9&&eq30.at1000>1.9&&eq20.at1000>eq20.at500&&eq30.at1000>eq30.at500,neutral:1,eq20,eq30});report.dataset.done='true'}catch(error){report.textContent=JSON.stringify({passed:false,error:String(error)});report.dataset.done='true'}})()}
